-- NEXORA MARKET schema. Run after enabling Supabase Auth.
create extension if not exists pgcrypto;
create type public.app_role as enum ('buyer','seller','admin');
create type public.product_status as enum ('draft','pending','approved','rejected','archived');
create type public.order_status as enum ('pending','confirmed','packed','shipped','delivered','cancelled');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, display_name text not null check (char_length(display_name) between 1 and 120), phone text, avatar_url text, role public.app_role not null default 'buyer', created_at timestamptz not null default now());
create table public.seller_profiles(id uuid primary key references public.profiles(id) on delete cascade, store_name text not null, bio text, payout_note text, commission_rate numeric(5,2) not null default 5.00 check (commission_rate between 0 and 100), approved boolean not null default false);
create table public.categories(id uuid primary key default gen_random_uuid(), name text not null unique, slug text not null unique, created_at timestamptz not null default now());
create table public.products(id uuid primary key default gen_random_uuid(), seller_id uuid not null references public.seller_profiles(id) on delete cascade, category_id uuid references public.categories(id), name text not null check (char_length(name) between 1 and 180), description text, price_mmk integer not null check (price_mmk>0), stock integer not null default 0 check (stock>=0), status public.product_status not null default 'draft', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.product_images(id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, storage_path text not null, sort_order integer not null default 0);
create table public.wishlists(user_id uuid not null references public.profiles(id) on delete cascade, product_id uuid not null references public.products(id) on delete cascade, created_at timestamptz not null default now(), primary key(user_id,product_id));
create table public.carts(user_id uuid not null references public.profiles(id) on delete cascade, product_id uuid not null references public.products(id) on delete cascade, quantity integer not null check (quantity>0), updated_at timestamptz not null default now(), primary key(user_id,product_id));
create table public.orders(id uuid primary key default gen_random_uuid(), buyer_id uuid not null references public.profiles(id), status public.order_status not null default 'pending', payment_method text not null default 'cod' check (payment_method='cod'), payment_status text not null default 'pending' check (payment_status in ('pending','paid','failed','refunded')), total_mmk integer not null check (total_mmk>0), delivery_name text not null, delivery_phone text not null, delivery_address text not null, created_at timestamptz not null default now());
create table public.order_items(id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, product_id uuid not null references public.products(id), seller_id uuid not null references public.seller_profiles(id), product_name text not null, unit_price_mmk integer not null, quantity integer not null check (quantity>0));
create table public.commissions(id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, seller_id uuid not null references public.seller_profiles(id), gross_mmk integer not null, rate numeric(5,2) not null, commission_mmk integer not null, payout_mmk integer not null, created_at timestamptz not null default now());
create table public.advertisements(id uuid primary key default gen_random_uuid(), seller_id uuid references public.seller_profiles(id), title text not null, placement text not null, budget_mmk integer not null default 0, active boolean not null default false, created_at timestamptz not null default now());
create table public.reports(id uuid primary key default gen_random_uuid(), reporter_id uuid not null references public.profiles(id), product_id uuid references public.products(id), order_id uuid references public.orders(id), reason text not null, status text not null default 'open' check (status in ('open','investigating','resolved','dismissed')), created_at timestamptz not null default now());
create table public.moderation_actions(id uuid primary key default gen_random_uuid(), admin_id uuid not null references public.profiles(id), product_id uuid references public.products(id), report_id uuid references public.reports(id), action text not null, note text, created_at timestamptz not null default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin') $$;
create or replace function public.is_seller() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role in ('seller','admin')) $$;
alter table public.profiles enable row level security; alter table public.seller_profiles enable row level security; alter table public.categories enable row level security; alter table public.products enable row level security; alter table public.product_images enable row level security; alter table public.wishlists enable row level security; alter table public.carts enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.commissions enable row level security; alter table public.advertisements enable row level security; alter table public.reports enable row level security; alter table public.moderation_actions enable row level security;
create policy profiles_self on public.profiles for all using (id=auth.uid() or public.is_admin()) with check (id=auth.uid() or public.is_admin());
create policy sellers_public_read on public.seller_profiles for select using (approved=true or id=auth.uid() or public.is_admin()); create policy sellers_self on public.seller_profiles for all using (id=auth.uid() or public.is_admin()) with check (id=auth.uid() or public.is_admin());
create policy categories_public_read on public.categories for select using (true); create policy categories_admin_write on public.categories for all using (public.is_admin()) with check (public.is_admin());
create policy products_public_read on public.products for select using (status='approved' or public.is_seller() and seller_id=auth.uid() or public.is_admin()); create policy products_seller_write on public.products for insert with check (seller_id=auth.uid() and public.is_seller()); create policy products_seller_update on public.products for update using (seller_id=auth.uid() or public.is_admin()) with check (seller_id=auth.uid() or public.is_admin());
create policy wishlist_owner on public.wishlists for all using (user_id=auth.uid()) with check (user_id=auth.uid()); create policy cart_owner on public.carts for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy orders_buyer_read on public.orders for select using (buyer_id=auth.uid() or public.is_admin()); create policy orders_buyer_insert on public.orders for insert with check (buyer_id=auth.uid()); create policy orders_admin_update on public.orders for update using (public.is_admin());
create policy order_items_owner_read on public.order_items for select using (exists(select 1 from public.orders o where o.id=order_id and (o.buyer_id=auth.uid() or public.is_admin())) or seller_id=auth.uid());
create policy commissions_owner_read on public.commissions for select using (seller_id=auth.uid() or public.is_admin()); create policy ads_public_read on public.advertisements for select using (active=true or seller_id=auth.uid() or public.is_admin()); create policy ads_owner_write on public.advertisements for all using (seller_id=auth.uid() or public.is_admin()) with check (seller_id=auth.uid() or public.is_admin());
create policy reports_owner_read on public.reports for select using (reporter_id=auth.uid() or public.is_admin()); create policy reports_owner_insert on public.reports for insert with check (reporter_id=auth.uid()); create policy reports_admin_update on public.reports for update using (public.is_admin()); create policy moderation_admin_only on public.moderation_actions for all using (public.is_admin()) with check (public.is_admin());
